CREATE OR REPLACE FUNCTION public.ui_reviews_page(p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_query text DEFAULT NULL::text, p_domain text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_sort text DEFAULT 'priority'::text, p_direction text DEFAULT 'desc'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'workflow', 'auth'
AS $function$ declare v_limit int:=least(greatest(coalesce(p_limit,50),1),200);v_offset int:=greatest(coalesce(p_offset,0),0);v_dir text:=case when lower(coalesce(p_direction,'desc'))='asc' then 'asc' else 'desc' end; begin if auth.uid() is null then raise exception 'authentication required'; end if; return (with base as(select r.id,r.entity_id,r.domain,r.field_code,r.priority,r.status,r.reopen_reason,r.created_at,r.updated_at from workflow.review_queue r where (nullif(trim(coalesce(p_query,'')),'') is null or coalesce(r.domain,'') ilike '%'||trim(p_query)||'%' or coalesce(r.field_code,'') ilike '%'||trim(p_query)||'%' or coalesce(r.reopen_reason,'') ilike '%'||trim(p_query)||'%') and (nullif(trim(coalesce(p_domain,'')),'') is null or r.domain=trim(p_domain)) and (nullif(trim(coalesce(p_status,'')),'') is null or r.status=trim(p_status))),numbered as(select *,count(*) over() total_count from base),ordered as(select * from numbered order by case when v_dir='asc' then priority end asc,case when v_dir='desc' then priority end desc,created_at desc,id limit v_limit offset v_offset) select jsonb_build_object('items',coalesce(jsonb_agg(to_jsonb(o)-'total_count'),'[]'::jsonb),'total',coalesce(max(total_count),0),'limit',v_limit,'offset',v_offset) from ordered o); end $function$
